#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

class LinkedQueue {
private:
    Node* front;
    Node* rear;
public:
    LinkedQueue() {
        front = rear = nullptr;
    }
    bool isEmpty() {
        return front == nullptr;
    }
    void enqueue(int value) {
        Node* newNode = new Node();
        newNode->data = value;
        newNode->next = nullptr;
        if (rear == nullptr) {
            front = rear = newNode;
        } else {
            rear->next = newNode;
            rear = newNode;
        }
        cout << value << " joins the queue" << endl;
    }
    void dequeue() {
        if (isEmpty()) {
            cout << "The queue is empty" << endl;
            return;
        }
        Node* temp = front;
        front = front->next;
        cout << temp->data << " leaves the queue" << endl;
        delete temp;
        if (front == nullptr) {
            rear = nullptr;
        }
    }
};

int main() {
    LinkedQueue q;
    q.enqueue(10);
    q.enqueue(20);
    q.dequeue();
    q.dequeue();
    q.enqueue(30);
    q.dequeue();
    return 0;
}
